var n=`1351-llapingachos`;var i=`world-1351`;var t=`EC`;var a=`south-america`;var s=4;var r=66;var d={en:`Llapingachos`,ua:`Льяпінгачос`};var g={en:`Llapingachos is a dish from Ecuador featuring potato, queso fresco, chicken egg, green onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Льяпінгачос, страва кухні країни Еквадор з такими основними складниками: картопля, кесо фреско, куряче яйце, зелена цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`potato`,750,`g`],[`water`,1100,`ml`],[`table-salt`,8,`g`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 10 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 10 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:10,i:[[`queso-fresco`,220,`g`],[`chicken-egg`,2,`pcs`],[`green-onion`,45,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`canola-oil`,100,`ml`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`avocado`,2,`pcs`],[`peanut-sauce`,90,`g`]]}];var u={slug:n,id:i,country:`EC`,region:a,servings:4,minutes:66,title:d,text:g,steps:h};export{t as country,u as default,i as id,r as minutes,a as region,s as servings,n as slug,h as steps,g as text,d as title};